package echo

import (
	"net/http"
	"testing"

	"github.com/stretchr/testify/assert"
)

func TestMultipleGroupSamePathMiddleware(t *testing.T) {
	e := New()

	mw := func(name string) MiddlewareFunc {
		return func(next HandlerFunc) HandlerFunc {
			return func(c Context) error {
				c.Response().Header().Add("X-MW", name)
				return next(c)
			}
		}
	}

	g1 := e.Group("/api")
	g1.Use(mw("one"))
	g1.GET("/one", func(c Context) error { return c.String(http.StatusOK, "one") })

	g2 := e.Group("/api")
	g2.Use(mw("two"))
	g2.GET("/two", func(c Context) error { return c.String(http.StatusOK, "two") })

	// route 1 must run only group1 middleware
	c, body := request(http.MethodGet, "/api/one", e)
	assert.Equal(t, http.StatusOK, c)
	assert.Equal(t, "one", body)
	assert.Equal(t, []string{"one"}, e.routers[""].routes[http.MethodGet+"/api/one"].Middleware)

	// route 2 must run only group2 middleware
	c, body = request(http.MethodGet, "/api/two", e)
	assert.Equal(t, http.StatusOK, c)
	assert.Equal(t, "two", body)

	// fallback for the prefix must be 404
	c, _ = request(http.MethodGet, "/api/unknown", e)
	assert.Equal(t, http.StatusNotFound, c)
	c, _ = request(http.MethodGet, "/api", e)
	assert.Equal(t, http.StatusNotFound, c)

	// also check middleware actually applied via headers
	req := newRequest(http.MethodGet, "/api/one")
	rec := newRecorder()
	e.ServeHTTP(rec, req)
	assert.Equal(t, []string{"one"}, rec.Header().Values("X-MW"))

	req = newRequest(http.MethodGet, "/api/two")
	rec = newRecorder()
	e.ServeHTTP(rec, req)
	assert.Equal(t, []string{"two"}, rec.Header().Values("X-MW"))
}

